import { useState } from "react";
import "./Text.css"; // Create this CSS file

const Text = () => {
  const [inputText, setInputText] = useState("");

  const handleKeyClick = (char) => {
    setInputText((prev) => prev + char);
  };

  const handleReset = () => {
    setInputText("");
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    console.log("Submitted text:", inputText);

    try {
      const result = await fetch("http://localhost:3000/send-test", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ text: inputText }),
      });
      console.log("Server response:", await result.json());
    } catch (err) {
      console.error("Error:", err);
    }
  };

  const characters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789".split("");

  return (
    <div className="container">
      <h2 className="heading">Text</h2>
      <div className="button-group">
        <button className="action-btn" onClick={handleSubmit}>Submit</button>
        <button className="action-btn" onClick={handleReset}>Reset</button>
      </div>

      <div className="keyboard">
        {characters.map((char, index) => (
          <button key={index} className="key" onClick={() => handleKeyClick(char)}>
            {char}
          </button>
        ))}
      </div>
    </div>
  );
};

export default Text;
